    rows = db.scalars(
        select(OrgMember)
        .where(or_(OrgMember.fio.ilike(f"%{safe}%"), OrgMember.position.ilike(f"%{safe}%")))
        .limit(15)
    ).all()
    items = []
    for member in rows:
        if is_liquidated(member.department) or is_liquidated(member.position) or is_liquidated(member.fio):
