def _norm_names() -> list[str]:
    if not NORMS_DIR.is_dir():
        raise OSError(str(NORMS_DIR))
    names: list[str] = []
    for item in NORMS_DIR.iterdir():
        if item.is_file():
            names.append(item.name)
        elif item.is_dir():
            for child in item.iterdir():
                if child.is_file():
                    names.append(f"{item.name}/{child.name}")
        if len(names) >= 400:
            break
    return names


