    python = sys.executable
    if sys.platform == "win32":
        path = workspace / "lookup.cmd"
        path.write_text(
            f'@echo off\r\nset "PYTHONPATH={BACKEND_DIR}"\r\n"{python}" -m app.services.server_agents %*\r\n',
